package com.bakeflow.audit;
import java.sql.Timestamp;import java.time.Instant;import java.util.UUID;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import tools.jackson.databind.ObjectMapper;
@Service public class AuditService{private final JdbcTemplate jdbc;private final ObjectMapper json;public AuditService(JdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}public void record(String event,String entity,UUID id,String description,Object metadata){String value;try{value=json.writeValueAsString(metadata);}catch(Exception e){value="{}";}jdbc.update("INSERT INTO audit_events(id,event_type,entity_type,entity_id,actor_type,description,metadata,occurred_at) VALUES(?,?,?,?,?,?,CAST(? AS JSONB),?)",UUID.randomUUID(),event,entity,id,"SYSTEM",description,value,Timestamp.from(Instant.now()));}}
